package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"syscall"
	"time"
)

// installedFile records exactly the generated bytes or shell block owned by in.
type installedFile struct {
	Path  string
	Block string `json:",omitempty"`
	Hash  string `json:",omitempty"`
}

// installation is an undo manifest, not an SSH host or credential store.
type installation struct{ Files []installedFile }

// edit stages a validated replacement and its rollback snapshot.
type edit struct {
	path          string
	before, after []byte
	mode          os.FileMode
	existed       bool
}

// setup installs reversible browser or laptop integration using existing SSH configuration.
func setup(ctx context.Context, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("use setup remote or setup laptop HOST")
	}
	role := args[0]
	if role != "remote" && role != "laptop" {
		return fmt.Errorf("setup role must be remote or laptop")
	}
	f := flag.NewFlagSet("setup", flag.ContinueOnError)
	f.SetOutput(io.Discard)
	shellFile := f.String("shell-file", "", "shell initialization file")
	sshConfig := f.String("ssh-config", "", "alternate SSH configuration file")
	remote := f.String("remote", ".local/share/in/bin/in", "installed remote executable")
	if f.Parse(args[1:]) != nil {
		return fmt.Errorf("invalid setup arguments; flags precede the host")
	}
	if (role == "remote" && f.NArg() != 0) || (role == "laptop" && f.NArg() != 1) {
		return fmt.Errorf("use setup remote or setup laptop HOST")
	}
	root, err := stateDir()
	if err != nil {
		return err
	}
	if strings.ContainsAny(root, " \t\r\n%:\"\\") {
		return fmt.Errorf("installation path cannot contain whitespace, colon or percent")
	}
	owner, err := lock(filepath.Join(root, "setup.lock"))
	if err != nil {
		return fmt.Errorf("another setup is running")
	}
	defer func() {
		if owner != nil {
			owner.Close()
		}
	}()
	manifest, err := readInstallation(root)
	if err != nil {
		return err
	}
	exe, err := os.Executable()
	if err != nil {
		return err
	}
	binary, err := os.ReadFile(exe)
	if err != nil {
		return err
	}
	if err = privateDir(filepath.Join(root, "bin")); err != nil {
		return err
	}
	installed := filepath.Join(root, "bin", "in")
	changes := []edit{}
	addFile := func(path string, data []byte, mode os.FileMode) error {
		old, exists, err := readOwned(path)
		if err != nil {
			return err
		}
		prior := findInstalled(manifest, path, "")
		if exists && (prior == nil || hashBytes(old) != prior.Hash) {
			return fmt.Errorf("refusing to overwrite an unowned or modified generated file")
		}
		changes = append(changes, edit{path, old, data, mode, exists})
		record(&manifest, installedFile{Path: path, Hash: hashBytes(data)})
		return nil
	}
	addBlock := func(path, marker, content string) error {
		path, err = filepath.Abs(path)
		if err != nil {
			return err
		}
		old, exists, err := readOwned(path)
		if err != nil {
			return err
		}
		text := string(old)
		start := "# >>> in:" + marker + " >>>\n"
		end := "# <<< in:" + marker + " <<<\n"
		prior := findInstalled(manifest, path, start)
		if prior != nil {
			if strings.Count(text, prior.Block) != 1 {
				return fmt.Errorf("managed shell/SSH block was edited; restore it before setup")
			}
			text = strings.Replace(text, prior.Block, "", 1)
		} else if strings.Contains(text, start) {
			return fmt.Errorf("existing managed block has no ownership record")
		}
		block := start + content + "\n" + end
		mode := os.FileMode(0600)
		if exists {
			info, _ := os.Stat(path)
			mode = info.Mode().Perm()
		}
		changes = append(changes, edit{path, old, []byte(block + text), mode, exists})
		record(&manifest, installedFile{Path: path, Block: block})
		return nil
	}
	if err = addFile(installed, binary, 0700); err != nil {
		return err
	}
	var snippet string
	var activation *peer
	if role == "remote" {
		browser := filepath.Join(root, "bin", "browser")
		openers := filepath.Join(root, "openers")
		if err = privateDir(openers); err != nil {
			return err
		}
		// A tiny launcher avoids relying on BROWSER's inconsistent argument splitting.
		script := "#!/bin/sh\nIN_HOME=" + shellQuote(root) + " exec " + shellQuote(installed) + " browse \"$@\"\n"
		if err = addFile(browser, []byte(script), 0700); err != nil {
			return err
		}
		// Keep the xdg-open shim outside bin so only guarded remote shells see it.
		opener := "#!/bin/sh\nIN_HOME=" + shellQuote(root) + " exec " + shellQuote(installed) + " open \"$@\"\n"
		if err = addFile(filepath.Join(openers, "xdg-open"), []byte(opener), 0700); err != nil {
			return err
		}
		snippet = "if { [ -n \"${SSH_CONNECTION:-}\" ] || [ -n \"${IN_SESSION_SOCKET:-}\" ]; } && { [ -z \"${BROWSER:-}\" ] || [ \"$BROWSER\" = " + shellQuote(browser) + " ]; }; then\n  export IN_HOME=" + shellQuote(root) + "\n  export BROWSER=" + shellQuote(browser) + "\n  case :\"$PATH\": in\n    *:" + shellQuote(openers) + ":*) ;;\n    *) export PATH=" + shellQuote(openers) + ":\"$PATH\" ;;\n  esac\nfi"
	} else {
		host := f.Arg(0)
		if strings.ContainsAny(*remote+*sshConfig, "\r\n%") {
			return fmt.Errorf("SSH hook paths cannot contain newlines or percent tokens")
		}
		activation = &peer{Host: host, Config: *sshConfig, Remote: *remote}
		if !regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`).MatchString(host) {
			return fmt.Errorf("use an existing SSH Host alias without shell syntax")
		}
		home, _ := os.UserHomeDir()
		configPath := *sshConfig
		if configPath == "" {
			configPath = filepath.Join(home, ".ssh", "config")
		}
		configPath, err = filepath.Abs(configPath)
		if err != nil {
			return err
		}
		// Remove our prior include in a temporary copy before inspecting the user's settings.
		configData, exists, err := readOwned(configPath)
		if err != nil {
			return err
		}
		for _, item := range manifest.Files {
			if item.Path == configPath && item.Block != "" {
				configData = []byte(strings.ReplaceAll(string(configData), item.Block, ""))
			}
		}
		opts, err := sshOptions(ctx, host, configData, exists, configPath, *sshConfig != "")
		if err != nil {
			return err
		}
		if opts["localcommand"] != "" && opts["localcommand"] != "none" {
			return fmt.Errorf("this host already has LocalCommand; automatic hook composition is not supported")
		}
		control := opts["controlpath"]
		ownedControl := control == "" || control == "none"
		if ownedControl {
			if err = privateDir(filepath.Join(root, "c")); err != nil {
				return err
			}
			control = filepath.Join(root, "c", "%C")
		}
		if strings.ContainsAny(control, "\n\r'\" ") {
			return fmt.Errorf("existing ControlPath cannot be used safely by the connection hook")
		}
		hook := "IN_HOME=" + shellQuote(root) + " " + shellQuote(installed) + " connect --key '%C' --host " + shellQuote(host) + " --control " + shellQuote(control) + " --remote " + shellQuote(*remote)
		if *sshConfig != "" {
			hook += " --config " + shellQuote(configPath)
		}
		// For an existing resolved path, reject connection overrides rather than join a different master.
		if !ownedControl {
			probeArgs := []string{"-G", "-o", "ControlPath=/in-key/%C"}
			if *sshConfig != "" {
				probeArgs = append(probeArgs, "-F", configPath)
			}
			probeArgs = append(probeArgs, host)
			out, e := exec.CommandContext(ctx, "ssh", probeArgs...).Output()
			if e != nil {
				return fmt.Errorf("cannot verify existing SSH control path")
			}
			expected := filepath.Base(parseOptions(string(out))["controlpath"])
			hook += " --expected-key " + shellQuote(expected)
		}
		stanza := "Host " + host + "\n  PermitLocalCommand yes\n  LocalCommand " + hook + "\n"
		if ownedControl {
			stanza += "  ControlPath " + control + "\n"
		}
		if opts["controlmaster"] == "false" || opts["controlmaster"] == "no" || opts["controlmaster"] == "" {
			stanza += "  ControlMaster auto\n"
		}
		if opts["controlpersist"] == "no" || opts["controlpersist"] == "0" || opts["controlpersist"] == "" {
			stanza += "  ControlPersist 60\n"
		}
		stanza += "Host *\n"
		fragment := filepath.Join(root, "ssh-"+digest(host)+".conf")
		if err = addFile(fragment, []byte(stanza), 0600); err != nil {
			return err
		}
		if err = addBlock(configPath, "ssh-"+digest(host), "Include \""+fragment+"\""); err != nil {
			return err
		}
		// Mosh's proxy startup sets -S none. This mode retains SSH multiplexing.
		snippet = "if ! alias mosh >/dev/null 2>&1 && ! typeset -f mosh >/dev/null 2>&1; then\n  mosh() { command mosh --experimental-remote-ip=remote \"$@\"; }\nfi\n" +
			"if ! alias et >/dev/null 2>&1 && ! typeset -f et >/dev/null 2>&1; then\n  et() { if [ -x " + shellQuote(installed) + " ]; then IN_HOME=" + shellQuote(root) + " " + shellQuote(installed) + " terminal et \"$@\"; else command et \"$@\"; fi; }\nfi"
	}
	snippetPath := filepath.Join(root, role+".sh")
	if err = addFile(snippetPath, []byte(snippet+"\n"), 0600); err != nil {
		return err
	}
	shellFiles := []string{*shellFile}
	if *shellFile == "" {
		home, _ := os.UserHomeDir()
		switch filepath.Base(os.Getenv("SHELL")) {
		case "zsh":
			shellFiles = []string{filepath.Join(home, ".zshrc")}
		case "bash", "":
			shellFiles = []string{filepath.Join(home, ".bashrc"), filepath.Join(home, ".bash_profile")}
		default:
			return fmt.Errorf("automatic setup supports bash and zsh; specify --shell-file for another initialization path")
		}
	}
	for _, path := range shellFiles {
		if err = addBlock(path, role, "[ ! -r "+shellQuote(snippetPath)+" ] || . "+shellQuote(snippetPath)); err != nil {
			return err
		}
	}
	data, _ := json.MarshalIndent(manifest, "", "  ")
	manifestPath := filepath.Join(root, "install.json")
	old, exists, err := readOwned(manifestPath)
	if err != nil {
		return err
	}
	changes = append(changes, edit{manifestPath, old, append(data, '\n'), 0600, exists})
	// An older relay may speak a different wire version. Let its own installed
	// executable stop it before replacement, while preserving SSH masters and ET terminals.
	if changes[0].existed && string(changes[0].before) != string(changes[0].after) {
		// The previous binary may itself take setup.lock while stopping.
		owner.Close()
		upgradeCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		command := exec.CommandContext(upgradeCtx, installed, "stop")
		command.Stdout = io.Discard
		command.Stderr = io.Discard
		stopErr := command.Run()
		cancel()
		owner, err = lock(filepath.Join(root, "setup.lock"))
		if err != nil {
			return fmt.Errorf("another setup is running")
		}
		if stopErr != nil {
			return fmt.Errorf("previous integration could not stop; retry setup after stopping it")
		}
	}
	if err = applyEdits(changes); err != nil {
		return err
	}
	if activation != nil {
		activateExisting(ctx, installed, *activation)
	}
	fmt.Println("Installed", role, "integration. Open a new terminal for shell changes.")
	if role == "laptop" {
		fmt.Println("This host's remote account can request browser opens. Existing SSH credentials remain managed by SSH.")
	}
	return nil
}

// activateExisting attaches once during setup because multiplexed slaves may bypass LocalCommand.
func activateExisting(parent context.Context, installed string, p peer) {
	ctx, cancel := context.WithTimeout(parent, 2*time.Second)
	defer cancel()
	args := []string{"-G"}
	if p.Config != "" {
		args = append(args, "-F", p.Config)
	}
	args = append(args, p.Host)
	output, err := exec.CommandContext(ctx, "ssh", args...).Output()
	if err != nil {
		return
	}
	p.Control = parseOptions(string(output))["controlpath"]
	if p.Control == "" || p.Control == "none" {
		return
	}
	check := []string{"-S", p.Control, "-O", "check"}
	if p.Config != "" {
		check = append(check, "-F", p.Config)
	}
	check = append(check, "--", p.Host)
	cmd := exec.CommandContext(ctx, "ssh", check...)
	if cmd.Run() != nil {
		return
	}
	hook := []string{"connect", "--host", p.Host, "--control", p.Control, "--remote", p.Remote}
	if p.Config != "" {
		hook = append(hook, "--config", p.Config)
	}
	_ = exec.CommandContext(ctx, installed, hook...).Run()
}

// sshOptions asks OpenSSH to interpret the user's configuration without our generated blocks.
func sshOptions(ctx context.Context, host string, data []byte, exists bool, path string, custom bool) (map[string]string, error) {
	args := []string{"-G"}
	if exists {
		if !custom {
			data = append(data, []byte("\nHost *\nInclude /etc/ssh/ssh_config\n")...)
		}
		// Keep the temporary config beside the original so relative Include behavior stays consistent.
		file, err := os.CreateTemp(filepath.Dir(path), ".in-config-")
		if err != nil {
			return nil, fmt.Errorf("cannot inspect SSH configuration")
		}
		defer os.Remove(file.Name())
		if _, err = file.Write(data); err != nil {
			file.Close()
			return nil, err
		}
		file.Close()
		args = append(args, "-F", file.Name())
	} else if custom {
		// A new custom file starts empty; do not inherit the unrelated default configuration.
		args = append(args, "-F", os.DevNull)
	}
	args = append(args, host)
	command := exec.CommandContext(ctx, "ssh", args...)
	command.Stderr = io.Discard
	out, err := command.Output()
	if err != nil {
		return nil, fmt.Errorf("SSH cannot resolve this host's configuration")
	}
	return parseOptions(string(out)), nil
}

// parseOptions reads only OpenSSH's own normalized output, never private key material.
func parseOptions(text string) map[string]string {
	result := map[string]string{}
	for _, line := range strings.Split(text, "\n") {
		key, value, ok := strings.Cut(line, " ")
		if ok {
			result[key] = strings.TrimSpace(value)
		}
	}
	return result
}

// readOwned rejects symlinks before planning a reversible file replacement.
func readOwned(path string) ([]byte, bool, error) {
	info, err := os.Lstat(path)
	if os.IsNotExist(err) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	if !info.Mode().IsRegular() {
		return nil, false, fmt.Errorf("setup requires regular files; resolve symlinked configuration explicitly")
	}
	data, err := os.ReadFile(path)
	return data, true, err
}

// hashBytes records content ownership without keeping copies of generated binaries.
func hashBytes(data []byte) string { sum := sha256.Sum256(data); return hex.EncodeToString(sum[:]) }

// readInstallation loads the small undo manifest and refuses corrupted state.
func readInstallation(root string) (installation, error) {
	var m installation
	data, err := os.ReadFile(filepath.Join(root, "install.json"))
	if os.IsNotExist(err) {
		return m, nil
	}
	if err != nil || json.Unmarshal(data, &m) != nil {
		return m, fmt.Errorf("cannot read installation ownership record")
	}
	return m, nil
}

// findInstalled finds a generated file or an exact managed block by its start marker.
func findInstalled(m installation, path, start string) *installedFile {
	for _, item := range m.Files {
		if item.Path == path && ((start == "" && item.Block == "") || (start != "" && strings.HasPrefix(item.Block, start))) {
			copy := item
			return &copy
		}
	}
	return nil
}

// record replaces one owned entry while preserving installations for other roles and hosts.
func record(m *installation, item installedFile) {
	for i, old := range m.Files {
		if old.Path == item.Path {
			if old.Block == "" && item.Block == "" {
				m.Files[i] = item
				return
			}
			a, _, _ := strings.Cut(old.Block, "\n")
			b, _, _ := strings.Cut(item.Block, "\n")
			if a == b {
				m.Files[i] = item
				return
			}
		}
	}
	m.Files = append(m.Files, item)
}

// atomicWrite replaces one file using a private same-directory temporary file.
func atomicWrite(path string, data []byte, mode os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return err
	}
	file, err := os.CreateTemp(filepath.Dir(path), ".in-write-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	if err = file.Chmod(mode); err == nil {
		_, err = file.Write(data)
	}
	if err == nil {
		err = file.Sync()
	}
	closeErr := file.Close()
	if err != nil {
		return err
	}
	if closeErr != nil {
		return closeErr
	}
	return os.Rename(file.Name(), path)
}

// applyEdits validates the snapshots, then rolls back applied changes on a write failure.
func applyEdits(changes []edit) error {
	for _, change := range changes {
		data, exists, err := readOwned(change.path)
		if err != nil || exists != change.existed || string(data) != string(change.before) {
			return fmt.Errorf("configuration changed during setup; retry after reviewing it")
		}
	}
	for i, change := range changes {
		if err := atomicWrite(change.path, change.after, change.mode); err != nil {
			restored := true
			for j := i - 1; j >= 0; j-- {
				old := changes[j]
				current, _, readErr := readOwned(old.path)
				if readErr != nil || string(current) != string(old.after) {
					restored = false
					continue
				}
				var undoErr error
				if old.existed {
					undoErr = atomicWrite(old.path, old.before, old.mode)
				} else {
					undoErr = os.Remove(old.path)
				}
				if undoErr != nil {
					restored = false
				}
			}
			if !restored {
				return fmt.Errorf("setup failed and some changes could not be restored; review managed files before retrying")
			}
			return fmt.Errorf("setup could not write a managed file; earlier changes were rolled back")
		}
	}
	return nil
}

// status reports coordinator reachability and the latest fixed diagnostic, never request URLs.
func status() error {
	root, err := stateDir()
	if err != nil {
		return err
	}
	paths, _ := filepath.Glob(filepath.Join(root, "l-*.sock"))
	count := 0
	for _, path := range paths {
		c, e := net.DialTimeout("unix", path, 100*time.Millisecond)
		if e == nil {
			_, _ = io.WriteString(c, "status\n")
			c.Close()
			count++
		}
	}
	fmt.Printf("%d laptop bridge connection(s) running.\n", count)
	if data, err := os.ReadFile(filepath.Join(root, "last-error")); err == nil && len(data) > 0 {
		lines := strings.Split(strings.TrimSpace(string(data)), "\n")
		fmt.Println("Last diagnostic:", lines[len(lines)-1])
	}
	return nil
}

// stop fences new registrations and waits for owned bridges, preserving SSH masters.
func stop() error {
	root, err := stateDir()
	if err != nil {
		return err
	}
	owner, err := lock(filepath.Join(root, "setup.lock"))
	if err != nil {
		return fmt.Errorf("another setup is running")
	}
	defer owner.Close()
	return stopOwned(root)
}

// stopOwned stops registered bridges while the caller holds setup.lock.
func stopOwned(root string) error {
	if _, err := startupStamp(root); err != nil {
		return err
	}
	if err := atomicWrite(filepath.Join(root, "start-stamp"), []byte(requestID()+"\n"), 0600); err != nil {
		return fmt.Errorf("cannot fence bridge startup")
	}
	deadline := time.Now().Add(8 * time.Second)
	for _, prefix := range []string{"l-", "r-"} {
		paths, _ := filepath.Glob(filepath.Join(root, prefix+"*.lock"))
		for _, path := range paths {
			if strings.Count(filepath.Base(path), ".") != 1 {
				continue
			}
			for {
				owner, err := lock(path)
				if err == nil {
					owner.Close()
					break
				}
				if (!errors.Is(err, syscall.EWOULDBLOCK) && !errors.Is(err, syscall.EAGAIN)) || time.Now().After(deadline) {
					return fmt.Errorf("bridge did not stop cleanly; retry before uninstalling")
				}
				// A lock can precede its socket or outlive it during shutdown; retry both states.
				socket := strings.TrimSuffix(path, ".lock") + ".sock"
				c, err := net.DialTimeout("unix", socket, 100*time.Millisecond)
				if err == nil {
					c.SetDeadline(time.Now().Add(200 * time.Millisecond))
					if prefix == "l-" {
						_, _ = io.WriteString(c, "stop\n")
					} else {
						_ = newWire(c, c).send(message{Kind: "stop"})
					}
					c.Close()
				}
				time.Sleep(20 * time.Millisecond)
			}
		}
	}
	return nil
}

// uninstall removes only unchanged generated files and exact owned configuration blocks.
func uninstall() error {
	root, err := stateDir()
	if err != nil {
		return err
	}
	owner, err := lock(filepath.Join(root, "setup.lock"))
	if err != nil {
		return fmt.Errorf("another setup is running")
	}
	defer owner.Close()
	manifest, err := readInstallation(root)
	if err != nil {
		return err
	}
	var changes []edit
	var remove []string
	positions := map[string]int{}
	for _, item := range manifest.Files {
		data, exists, err := readOwned(item.Path)
		if err != nil {
			return err
		}
		if !exists {
			continue
		}
		if item.Block != "" {
			start, _, _ := strings.Cut(item.Block, "\n")
			if !strings.Contains(string(data), start) {
				lines := strings.Split(strings.TrimSpace(item.Block), "\n")
				for _, line := range lines[1:] {
					if strings.TrimSpace(line) != "" && strings.Contains(string(data), line) {
						return fmt.Errorf("managed configuration block was partially edited; refusing to remove it")
					}
				}
				continue
			}
			if strings.Count(string(data), item.Block) != 1 {
				return fmt.Errorf("managed configuration block was modified; refusing to remove it")
			}
			pos, ok := positions[item.Path]
			if !ok {
				info, _ := os.Stat(item.Path)
				pos = len(changes)
				positions[item.Path] = pos
				changes = append(changes, edit{item.Path, data, data, info.Mode().Perm(), true})
			}
			changes[pos].after = []byte(strings.Replace(string(changes[pos].after), item.Block, "", 1))
		} else {
			if hashBytes(data) != item.Hash {
				return fmt.Errorf("generated file was modified; refusing to remove it")
			}
			remove = append(remove, item.Path)
		}
	}
	if err = applyEdits(changes); err != nil {
		return err
	}
	if err = stopOwned(root); err != nil {
		return err
	}
	for _, path := range remove {
		if err = os.Remove(path); err != nil {
			return err
		}
	}
	if err = os.Remove(filepath.Join(root, "install.json")); err != nil && !os.IsNotExist(err) {
		return err
	}
	fmt.Println("Removed owned integration. Open a new shell to discard its inherited hooks.")
	return nil
}
